示例：
```cpp
class Dog {
public:
    virtual void bark() { std::cout << "Woof!" << std::endl; }
};

class Bird {
public:
    virtual void chirp() { std::cout << "Chirp!" << std::endl; }
};

class DogBird : public Dog, public Bird {};

DogBird myConfusedAnimal;
myConfusedAnimal.bark();
myConfusedAnimal.chirp();
```
输出：
```text
Woof!
Chirp!
```
